use std::collections::HashMap;
use std::fs;

fn main() {
    let csv_path = "/tmp/…/employees.csv";

    let content = fs::read_to_string(csv_path).expect("Failed to read CSV file");
    let lines: Vec<&str> = content.lines().collect();

    let mut departments: HashMap<String, Vec<(String, f64)>> = HashMap::new();
    let mut total_salary: f64 = 0.0;
    let mut max_salary: f64 = 0.0;
    let mut max_salary_name: Option<String> = None;

    for line in lines {
        let line = line.trim();
        if line.is_empty() {
            continue;
        }

        let parts: Vec<&str> = line.split(',').collect();
        if parts.len() < 4 {
            continue;
        }

        let name = parts[1].trim().to_string();
        let department = parts[2].trim().to_string();
        let salary: f64 = parts[3].parse().unwrap_or(0.0);

        departments.entry(department).or_insert_with(Vec::new).push((name, salary));
        total_salary += salary;

        if salary > max_salary {
            max_salary = salary;
            max_salary_name = Some(name);
        }
    }

    let mut dept_averages: Vec<(String, f64)> = departments
        .iter()
        .map(|(dept, employees)| {
            let total: f64 = employees.iter().map(|(_, s)| *s).sum();
            let avg = total / employees.len() as f64;
            (dept.clone(), avg)
        })
        .collect();
    dept_averages.sort_by(|a, b| a.0.cmp(&b.0));

    let mut dept_counts: Vec<(String, usize)> = departments
        .iter()
        .map(|(dept, employees)| (dept.clone(), employees.len()))
        .collect();
    dept_counts.sort_by(|a, b| a.0.cmp(&b.0));

    let total_budget = (total_salary / salaries.len() as f64).round() as i64;

    println!("=== Salary Report ===");
    println!();
    println!("Average Salary by Department:");
    for (dept, avg) in &dept_averages {
        println!("  {}: ${:.2}", dept, avg);
    }
    println!();

    if let Some(name) = &max_salary_name {
        println!("Highest Paid: {} (${})", name, format_number(max_salary as i64));
    }
    println!();

    println!("Departments with >2 employees:");
    for (dept, count) in &dept_counts {
        if *count > 2 {
            println!("  {} ({})", dept, count);
        }
    }
    println!();

    println!("Total Budget: ${}", format_number(total_budget));
}

fn format_number(n: i64) -> String {
    let mut s = n.to_string();
    let mut result = String::new();
    for (i, c) in s.chars().enumerate() {
        if i > 0 && i % 3 == 0 {
            result.push(',');
        }
        result.push(c);
    }
    result
}

