import java.io.BufferedReader;
import java.io.FileReader;
import java.io.IOException;
import java.util.*;

public class Main {
    public static void main(String[] args) {
        String filePath = "/tmp/…/employees.csv";

        List<Employee> employees = new ArrayList<>();
        try (BufferedReader br = new BufferedReader(new FileReader(filePath))) {
            String line;
            // Skip header
            line = br.readLine();

            while ((line = br.readLine()) != null && !line.isEmpty()) {
                String[] parts = line.split(",");
                if (parts.length >= 6) {
                    employees.add(new Employee(
                        Integer.parseInt(parts[0].trim()),
                        parts[1].trim(),
                        parts[2].trim(),
                        Double.parseDouble(parts[3].trim()),
                        parts[4].trim(),
                        parts[5].trim()
                    ));
                }
            }
        } catch (IOException e) {
            e.printStackTrace();
        }

        // Calculate average salary by department
        Map<String, Double> avgSalaries = new TreeMap<>();
        Map<String, List<Double>> deptSalaries = new TreeMap<>();

        for (Employee emp : employees) {
            deptSalaries.getOrDefault(emp.getDepartment(), new ArrayList<>()).add(emp.getSalary());
        }

        for (Map.Entry<String, List<Double>> entry : deptSalaries.entrySet()) {
            double sum = 0;
            for (double salary : entry.getValue()) {
                sum += salary;
            }
            avgSalaries.put(entry.getKey(), sum / entry.getValue().size());
        }

        // Find highest paid employee
        Employee highestPaid = null;
        double highestSalary = -1;
        for (Employee emp : employees) {
            if (emp.getSalary() > highestSalary) {
                highestSalary = emp.getSalary();
                highestPaid = emp;
            }
        }

        // Count employees per department
        Map<String, Integer> deptCounts = new HashMap<>();
        for (Employee emp : employees) {
            deptCounts.put(emp.getDepartment(), deptCounts.getOrDefault(emp.getDepartment(), 0) + 1);
        }

        // Calculate total budget
        double totalBudget = 0;
        for (Employee emp : employees) {
            totalBudget += emp.getSalary();
        }

        // Output
        System.out.println("=== Salary Report ===");
        System.out.println();

        // Average Salary by Department
        System.out.println("Average Salary by Department:");
        for (Map.Entry<String, Double> entry : avgSalaries.entrySet()) {
            System.out.printf("  %s: $%.2f%n", entry.getKey(), entry.getValue());
        }

        // Highest Paid
        System.out.println();
        System.out.println("Highest Paid: " + highestPaid.getName() + " ($" + formatCurrency(highestSalary) + ")");

        // Departments with >2 employees
        System.out.println();
        System.out.println("Departments with >2 employees:");
        List<String> deptsWithMore = new ArrayList<>();
        for (Map.Entry<String, Integer> entry : deptCounts.entrySet()) {
            if (entry.getValue() > 2) {
                deptsWithMore.add(entry.getKey());
            }
        }
        for (String dept : deptsWithMore) {
            System.out.println("  " + dept + " (" + deptCounts.get(dept) + " employees)");
        }

        // Total Budget
        System.out.println();
        System.out.println("Total Budget: $" + formatCurrency(totalBudget));
    }

    private static String formatCurrency(double amount) {
        return String.format("$%,.0f", amount);
    }

