            else if (j->data.str_val[i] == '\r') fprintf(out, "\\r");
            else if (j->data.str_val[i] == '\t') fprintf(out, "\\t");
            else fprintf(out, "%c", j->data.str_val[i]);
        }
        fprintf(out, "\"");
        return 0;
    }
    if (j->type == JSON_ARRAY) {
        fprintf(out, "[");
        for (int i = 0; i < j->data.arr.count; i++) {
            if (i > 0) fprintf(out, ",");
            format_json(j->data.arr.items[i], indent, out);
