use std::collections::HashMap;
    use std::fs;

    fn main() {
        let path = "/tmp/…/app.log";
        let content = fs::read_to_string(path).expect("Failed to read log file");

        let mut level_counts: HashMap<String, usize> = HashMap::new();
        let mut error_component_counts: HashMap<String, usize> = HashMap::new();
        let mut error_messages: Vec<String> = Vec::new();
        let mut hour_counts: HashMap<String, usize> = HashMap::new();

        for line in content.lines() {
            let trimmed = line.trim();
            if trimmed.is_empty() {
                continue;
            }

            // Parse timestamp
            let bracket_idx = trimmed.find(']').expect("Missing ] in log entry");
            let timestamp_part = &trimmed[..bracket_idx];
            // timestamp_part: [YYYY-MM-DD HH:MM:SS]
            let time_part = &timestamp_part[1..bracket_idx]; // YYYY-MM-DD HH:MM:SS
            let parts: Vec<&str> = time_part.split_whitespace().collect();
            if parts.len() >= 2 {
                let hour = parts[1].chars().take(2).collect::<String>();
                hour_counts.insert(hour, hour_counts.get(&hour).copied().unwrap_or(0) + 1);
            }

            // Parse body
            let body_part = &trimmed[bracket_idx + 1..];
            let dash_idx = body_part.find(" - ").expect("Missing ' - ' in log entry");
            let level_part = &body_part[..dash_idx];
            let message = &body_part[dash_idx + 3..];

            // Parse Level and Component
            let level_part_words: Vec<&str> = level_part.split_whitespace().collect();
            let level = level_part_words.get(0).unwrap_or("").to_string();
            let component_raw = level_part_words.get(1).unwrap_or("");
            let component = component_raw.trim_start_matches('(').trim_end_matches(')').trim();

            // Count Level
            level_counts.insert(level, level_counts.get(&level).copied().unwrap_or(0) + 1);

            // Count Errors
            if level == "ERROR" && !component.is_empty() {
                error_component_counts.insert(component.to_string(), error_component_counts.get(component).copied().unwrap_or(0) + 1);
                error_messages.push(message.to_string());
            }
        }

        // Sort Levels
        let mut levels: Vec<String> = level_counts.keys().cloned().collect();
        levels.sort();

        // Find Busiest Hour
        let mut busiest_hour = String::new();
        let mut busiest_count = 0;
        for (h, c) in &hour_counts {
            if c > &busiest_count {
                busiest_count = *c;
                busiest_hour = h.clone();
            }
        }
        // If no entries, default to 00:00 (0 count)? Or empty?
        // Assuming at least one entry. If hour_counts empty, busiest_hour empty.
        if busiest_hour.is_empty() {
             busiest_hour = "00".to_string();
             busiest_count = 0;
        }

        // Find Component with Most Errors
        let mut most_error_component = String::new();
        let mut max_error_count = 0;
        for (comp, count) in &error_component_counts {
            if count > &max_error_count {
                max_error_count = *count;
                most_error_component = comp.clone();
            }
        }
        if most_error_component.is_empty() {
            most_error_component = "(none)".to_string();
        }

        // Sort Messages
        error_messages.sort();
        error_messages.dedup();

        // Output
        println!("=== Log Analysis ===");
        println!();
        println!("Entries by Level:");
        for l in &levels {
            println!("  {}: {}", l, level_counts[l]);
        }
        println!();
        println!("Component with Most Errors: {} ({}) errors", most_error_component, max_error_count);
        println!();
        println!("Unique Error Messages:");
        for m in &error_messages {
            println!("  - {}", m);
        }
        println!();
        println!("Busiest Hour: {}:{} ({}) entries", busiest_hour, "00", busiest_count);
    }

