#[derive(Clone)]
struct ExtensionData {
    files: Vec<(String, usize, usize)>,
    lines: usize,
    chars: usize,
}

fn walk_directory(path: &Path, project_tree: &str) -> Result<(), Box<dyn std::error::Error>> {
    let mut current_path_buf = path.to_path_buf();

    if !current_path_buf.exists() {
        return Err("Directory does not exist".into());
    }

    let mut entries = fs::read_dir(path)?;

    while let Some(entry) = entries.next_entry()? {
        let entry_path = entry.path();

        if entry_path.is_dir() {
            let rel_path = entry_path.strip_prefix(project_tree)?;
            walk_directory(&entry_path, project_tree)?;
        } else {
            let rel_path = entry_path.strip_prefix(project_tree)?;
            let rel_path_str = rel_path.to_string_lossy().to_string();
            let ext = entry_path.extension()
                .map(|e| e.to_string_lossy().to_string())
                .unwrap_or_else(|| String::from(""));

            if ext.is_empty() {
                continue;
            }

            let file_bytes = fs::read(&entry_path)?;
            let line_count = file_bytes.lines().count();
            let char_count = file_bytes.len();

            let mut ext_data = files_by_extension.entry(ext).or_insert_with(|| ExtensionData {
                files: Vec::new(),
                lines: 0,
                chars: 0,
            });

            ext_data.files.push((rel_path_str.clone(), line_count, char_count));
            ext_data.lines += line_count;
            ext_data.chars += char_count;
        }
    }

    Ok(())
}

