const adj: Map<string, Map<string, number>> = new Map();
const nodeSet = new Set(allNodes);

for (const node of allNodes) {
    adj.set(node, new Map());
}

for (const edge of edges) {
    const from = edge.from;
    const to = edge.to;
    const weight = edge.weight;

    if (!adj.has(from)) adj.set(from, new Map());
    if (!adj.has(to)) adj.set(to, new Map());

    adj.get(from)!.set(to, weight);
    adj.get(to)!.set(from, weight);
}

const startNode = 'A';
const dist: Map<string, number> = new Map();
const visited: Set<string> = new Set();

for (const node of allNodes) {
    dist.set(node, Infinity);
}
dist.set(startNode, 0);

// Dijkstra O(V^2)
while (visited.size < allNodes.length) {
    let minNode = '';
    let minDist = Infinity;

    for (const node of allNodes) {
        if (visited.has(node)) continue;
        const d = dist.get(node);
        if (d !== Infinity && d < minDist) {
            minDist = d;
            minNode = node;
        }
    }

    if (minNode === '' || minDist === Infinity) break;

    visited.add(minNode);

    const neighbors = adj.get(minNode);
    if (neighbors) {
        for (const [neighbor, weight] of neighbors.entries()) {
            if (!visited.has(neighbor)) {
                const newDist = minDist + weight;
                if (newDist < dist.get(neighbor)!) {
                    dist.set(neighbor, newDist);
                }
            }
        }
    }
}

