        try {
            Path basePath = Paths.get("/tmp/…/project_tree");

            Map<String, FileStats> statsByExtension = new TreeMap<>();

            Files.walkFileTree(basePath, new SimpleFileVisitor<Path>() {
                @Override
                public FileVisitResult preVisitDirectory(Path dir, BasicFileAttributes attrs) {
                    return FileVisitResult.CONTINUE;
                }

                @Override
                public FileVisitResult visitFile(Path file, BasicFileAttributes attrs) {
                    if (attrs.isRegularFile() && !Files.isSymbolicLink(file)) {
                        try {
                            String extension = getFileExtension(file);
                            if (extension != null) {
                                FileStats stats = new FileStats(extension);
                                stats.setLineCount(getLineCount(file));
                                stats.setCharacterCount(getCharacterCount(file));

                                statsByExtension.computeIfAbsent(extension, k -> new FileStats(k));
                                statsByExtension.get(extension).addFile(file, stats);
                            }
                        } catch (Exception e) {
                        }
                    }
                    return FileVisitResult.CONTINUE;
                }
            });

            System.out.println("=== File Tree Analysis ===");
            System.out.println();

            int totalFiles = 0;
            int totalLines = 0;
            int totalChars = 0;

            for (String ext : statsByExtension.keySet()) {
                FileStats stats = statsByExtension.get(ext);
                System.out.println("Extension: " + ext);
                System.out.println("  Files: " + stats.fileCount);
                System.out.println("  Total Lines: " + stats.totalLines);
                System.out.println("  Total Characters: " + stats.totalChars);

                List<Path> files = new ArrayList<>(stats.files);
                Collections.sort(files, Comparator.comparing(p -> p.toString()));

                for (Path file : files) {
                    String relativePath = file.toRelativeString(basePath);
                    if (!relativePath.isEmpty()) {
                        System.out.println("    " + relativePath + ": " + stats.getLine(file) + " lines, " + stats.getChars(file) + " chars");
