func analyzeDirectory(at path: String) -> [(extension: String, files: [(relativePath: String, lines: Int, chars: Int)])] {
    var extensionGroups: [String: [(relativePath: String, lines: Int, chars: Int)]] = [:]

    do {
        let fileManager = FileManager.default
        let fileURL = URL(string: path)!

        // Check if it's a directory
        if fileManager.fileExists(atPath: path) {
            let isDirectory = fileManager.attributesOfItem(atPath: path)?.contains(.isDirectory) == true

            if isDirectory == true {
                // Recursively walk the directory
                for entryURL in try fileManager.contentsOfDirectory(at: path, includingPropertiesForKeys: nil) {
                    let relativePath = entryURL.deletingLastPathComponent().path

                    // Skip symlinks
                    if fileManager.isSymbolicLink(atPath: entryURL.path) {
                        continue
                    }

                    if fileManager.fileExists(atPath: entryURL.path) {
                        if fileManager.attributesOfItem(atPath: entryURL.path)?.contains(.isDirectory) == true {
                            analyzeDirectory(at: entryURL.path)
                        } else {
                            let ext = entryURL.pathExtension.isEmpty ? "" : "." + entryURL.pathExtension

                            var lines = 0
                            var chars = 0

                            do {
                                let content = try String(contentsOf: entryURL, encoding: .utf8)
                                lines = content.components(separatedBy: "\n").count
                                chars = content.count
                            } catch {
                                // Try to read as binary if UTF-8 fails
                                do {
                                    let content = try Data(contentsOf: entryURL)
                                    chars = content.count
                                    // For binary files, line count is 0
                                    lines = 0
                                } catch {
                                    lines = 0
                                    chars = 0
                                }
                            }

                            extensionGroups[ext] ??= []
                            extensionGroups[ext]!.append((relativePath, lines, chars))
                        }
                    }
                }
            }
        }
    } catch {
        // Handle errors gracefully
    }

    // Sort extensions alphabetically, then files by relative path
    var sortedGroups: [(ext: String, files: [(relativePath: String, lines: Int, chars: Int)])] = []
    for ext in sortedGroups.keys.sorted() {
        let files = sortedGroups[ext] ?? []
        sortedGroups.append((ext, files.sorted { $0.0 < $1.0 }))
    }

    return sortedGroups
}

