#include <sys/stat.h>
#include <unistd.h>

#define BASE_PATH "/tmp/…/project_tree"
#define BASE_PATH_LEN (strlen(BASE_PATH))

typedef struct {
    char *rel_path;
    char *ext;
    int lines;
    int chars;
} FileNode;

static FileNode *files = NULL;
static int num_files = 0;
static int total_files = 0;
static int total_lines = 0;
static int total_chars = 0;

static int get_extension_len(const char *path) {
    char *dot = strrchr(path, '.');
    if (dot) {
        return strlen(dot);
    }
    return 0;
}

static void add_file_info(const char *full_path, const char *name) {
    // Calculate relative path
    size_t rel_len = strlen(name);
    FileNode *fn = malloc(sizeof(FileNode));
    fn->rel_path = malloc(rel_len + 1);
    fn->chars = 0;
    fn->lines = 0;
    fn->ext = malloc(1);
    fn->ext[0] = '\0';

    // Extract extension
    char *ext_str = malloc(strlen(name) + 1);
    strcpy(ext_str, name);
    char *dot = strrchr(ext_str, '.');
    if (dot) {
        fn->ext = malloc(strlen(dot) + 1);
        strcpy(fn->ext, dot);
    } else {
        fn->ext = malloc(1);
        fn->ext[0] = '\0';
    }

    // Calculate relative path
    char *rel_path = malloc(rel_len + 1);
    memcpy(rel_path, full_path + BASE_PATH_LEN, rel_len);
    rel_path[rel_len] = '\0';
    fn->rel_path = rel_path;

    // Count lines and chars
    FILE *fp = fopen(full_path, "rb");
    if (fp) {
        fseek(fp, 0, SEEK_END);
        long size = ftell(fp);
        fseek(fp, 0, SEEK_SET);
        fn->chars = size;

        // Count lines
        int lines = 0;
        int c;
        while ((c = fgetc(fp)) != EOF) {
            if (c == '\n') {
                lines++;
            }
        }
        fn->lines = lines;

        fclose(fp);
    } else {
        fprintf(stderr, "Error opening %s\n", full_path);
    }

    files = realloc(files, (num_files + 1) * sizeof(FileNode));
    files[num_files] = *fn;
    num_files++;
    total_files++;
    total_lines += fn->lines;
    total_chars += fn->chars;
}

static int compare_files(const void *a, const void *b) {
    const FileNode *fa = (const FileNode *)a;
    const FileNode *fb = (const FileNode *)b;
    int ext_cmp = strcmp(fa->ext, fb->ext);
    if (ext_cmp != 0) return ext_cmp;
    return strcmp(fa->rel_path, fb->rel_path);
}

static void free_files_array() {
    for (int i = 0; i < num_files; i++) {
        free(files[i].rel_path);
        free(files[i].ext);
    }
    free(files);
    files = NULL;
    num_files = 0;
}

static void walk_directory(const char *dir_path) {
    DIR *dir = opendir(dir_path);
    if (!dir) {
        fprintf(stderr, "Error opening directory %s\n", dir_path);
        return;
    }

    struct dirent *ent;
    while ((ent = readdir(dir)) != NULL) {
        char *full_path = malloc(strlen(dir_path) + strlen(ent->d_name) + 1);
        strcpy(full_path, dir_path);
        strcat(full_path, ent->d_name);

        struct stat st;
        if (lstat(full_path, &st) == 0) {
            if (S_ISLNK(st.st_mode)) {
                free(full_path);
                continue;
            }
            if (S_ISDIR(st.st_mode)) {
                walk_directory(full_path);
            } else if (S_ISREG(st.st_mode)) {
                add_file_info(full_path, ent->d_name);
            }
        }
        free(full_path);
    }
    closedir(dir);
}

