func multiply(_ A: [[Int]], _ B: [[Int]]) -> [[Int]] {
    let rows = A.count
    let cols = A[0].count
    let result = Array(repeating: Array(repeating: 0, count: cols), count: rows)

    for i in 0..<rows {
        for j in 0..<cols {
            for k in 0..<cols {
                result[i][j] += A[i][k] * B[k][j]
            }
        }
    }

    return result
}

func determinant(_ matrix: [[Int]]) -> Int {
    let rows = matrix.count
    let cols = matrix[0].count

    if rows != cols {
        return 0
    }

    if rows == 1 {
        return matrix[0][0]
    }

    if rows == 2 {
        let a = matrix[0][0]
        let b = matrix[0][1]
        let c = matrix[1][0]
        let d = matrix[1][1]
        return a * d - b * c
    }

    if rows == 3 {
        let a = matrix[0][0]
        let b = matrix[0][1]
        let c = matrix[0][2]
        let d = matrix[1][0]
        let e = matrix[1][1]
        let f = matrix[1][2]
        let g = matrix[2][0]
        let h = matrix[2][1]
        let i = matrix[2][2]

        return a * (e * i - f * h) - b * (d * i - f * g) + c * (d * h - e * g)
    }

    // For larger matrices, use cofactor expansion
    var det = 0
    for j in 0..<cols {
        let sub = Array(matrix.dropFirst().dropFirst().dropFirst())
        if sub.count == 2 && sub[0].count == 2 {
            det += matrix[0][j] * determinant(sub)
        } else if sub.count == 3 && sub[0].count == 3 {
            det += matrix[0][j] * determinant(sub)
        }
    }

    return det
}

