fn main() {
    // Define Matrix A
    let a: [[i32; 3]; 3] = [
        [1, 2, 3],
        [4, 5, 6],
        [7, 8, 9]
    ];

    // Define Matrix B
    let b: [[i32; 3]; 3] = [
        [9, 8, 7],
        [6, 5, 4],
        [3, 2, 1]
    ];

    // Compute C = A x B
    let mut c: [[i32; 3]; 3] = [[0; 3]; 3];
    for i in 0..3 {
        for j in 0..3 {
            for k in 0..3 {
                c[i][j] += a[i][k] * b[k][j];
            }
        }
    }

    // Compute determinant of C
    let det = determinant(&c);

    // Output
    println!("=== Matrix Operations ===");
    println!();
    print_matrix(&a);
    println!();
    print_matrix(&b);
    println!();
    print_matrix(&c);
    println!();
    println!("Determinant: {}", det);
}

fn determinant(matrix: &[[i32; 3]; 3]) -> i32 {
    let a = matrix[0][0];
    let b = matrix[0][1];
    let c = matrix[0][2];
    let d = matrix[1][0];
    let e = matrix[1][1];
    let f = matrix[1][2];
    let g = matrix[2][0];
    let h = matrix[2][1];
    let i = matrix[2][2];

    a * (e * i - f * h) - b * (d * i - f * g) + c * (d * h - e * g)
}

fn print_matrix(matrix: &[[i32; 3]; 3]) {
    for row in matrix {
        let formatted_row: String = row.iter().map(|v| format!("{:4}", v)).collect();
        println!("  {}", formatted_row);
    }
}
